I’m designing a purely fictional, local equipment-reservation reducer; no real reservation is processed. Each active unit needs 14 cm of decorative ribbon. Events are dictionaries: a create has a type, a unique nonempty string id, and a positive integer quantity; a cancel has a type and id. Identical creates for an ID are idempotent, conflicting reuse must reject, and cancellation before creation establishes a tombstone. Cancellation is idempotent. Malformed events, including boolean quantities, must reject.

My current implementation is:

```python
def reduce_events(events):
    active = {}
    for e in events:
        if e['type'] == 'create':
            active[e['id']] = e['quantity']
        elif e['type'] == 'cancel':
            active.pop(e['id'], None)
    return active
```

Trace a cancellation of `b` followed by its creation, alongside repeated identical creates and then a conflicting create for `a`. Show the state after each event and explain where this implementation violates the rules.

```python
def reduce_events(events):
    creates = {}
    tombstones = set()
    active = {}

    for event in events:
        if not isinstance(event, dict):
            raise ValueError('event must be a dictionary')
        kind = event.get('type')
        if kind == 'create':
            expected = {'type', 'id', 'quantity'}
        elif kind == 'cancel':
            expected = {'type', 'id'}
        else:
            raise ValueError('invalid event type')
        if event.keys() != expected:
            raise ValueError('invalid event fields')

        reservation_id = event['id']
        if not isinstance(reservation_id, str) or not reservation_id:
            raise ValueError('id must be a nonempty string')

        if kind == 'create':
            quantity = event['quantity']
            if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity <= 0:
                raise ValueError('quantity must be a positive integer')
            if reservation_id in creates:
                if creates[reservation_id] != quantity:
                    raise ValueError('conflicting create')
                continue
            creates[reservation_id] = quantity
            if reservation_id not in tombstones:
                active[reservation_id] = quantity
        else:
            tombstones.add(reservation_id)
            active.pop(reservation_id, None)

    return {'creates': creates, 'tombstones': tombstones, 'active': active}
```

The reducer accepts exactly the specified fields. Since `id` and `type` are fixed for each create, retaining its quantity retains the data needed to compare the original payload. Inputs are not modified; a conflict raises `ValueError`, including after cancellation.

The oracle validates and groups events by ID, then derives state from the set of creates and the presence of any cancellation. It does not replay the reducer’s transitions.

```python
from itertools import permutations

# Assumes reduce_events is defined as above.
def oracle(events):
    by_id = {}
    for event in events:
        if not isinstance(event, dict):
            raise ValueError('event must be a dictionary')
        kind = event.get('type')
        if kind not in ('create', 'cancel'):
            raise ValueError('invalid event type')
        fields = {'type', 'id', 'quantity'} if kind == 'create' else {'type', 'id'}
        if set(event) != fields:
            raise ValueError('invalid event fields')
        ident = event['id']
        if not isinstance(ident, str) or not ident:
            raise ValueError('invalid id')
        if kind == 'create':
            q = event['quantity']
            if isinstance(q, bool) or not isinstance(q, int) or q <= 0:
                raise ValueError('invalid quantity')
        by_id.setdefault(ident, []).append(event)

    creates, tombstones, active = {}, set(), {}
    for ident, items in by_id.items():
        quantities = {e['quantity'] for e in items if e['type'] == 'create'}
        if len(quantities) > 1:
            raise ValueError('conflicting creates')
        cancelled = any(e['type'] == 'cancel' for e in items)
        if cancelled:
            tombstones.add(ident)
        if quantities:
            quantity = next(iter(quantities))
            creates[ident] = quantity
            if not cancelled:
                active[ident] = quantity
    return {'creates': creates, 'tombstones': tombstones, 'active': active}

trace = [
    {'type': 'create', 'id': 'a', 'quantity': 2},
    {'type': 'create', 'id': 'a', 'quantity': 2},
    {'type': 'cancel', 'id': 'a'},
    {'type': 'create', 'id': 'b', 'quantity': 1},
]
expected = {'creates': {'a': 2, 'b': 1}, 'tombstones': {'a'}, 'active': {'b': 1}}
for ordering in permutations(trace):
    assert oracle(ordering) == expected
    assert reduce_events(ordering) == expected

bad_traces = [
    [{'type': 'create', 'id': 'a', 'quantity': True}],
    [{'type': 'create', 'id': '', 'quantity': 1}],
    [{'type': 'cancel', 'id': 'a', 'extra': 1}],
    [{'type': 'unknown', 'id': 'a'}],
    [{'type': 'create', 'id': 'a', 'quantity': 2},
     {'type': 'cancel', 'id': 'a'},
     {'type': 'create', 'id': 'a', 'quantity': 3}],
]
for events in bad_traces:
    for fn in (oracle, reduce_events):
        try:
            fn(events)
        except ValueError:
            pass
        else:
            raise AssertionError(f'{fn.__name__} accepted {events!r}')
```

The permutations cover cancellation both before and after creation; the explicit expected state also guards against both implementations agreeing on the same wrong result.
